it('keeps the usage an earlier round reported when a later round reports none', async () => {
  const usage: UsageMetadata = {inputTokens: 11, outputTokens: 3, totalTokens: 14};
  let seen: UsageMetadata | undefined;
  const hooks: OrchestratorHooks = {
    afterModelResponse: async (_session, _text, reported) => {
      seen = reported;
    },
  };
  const orchestrator = createChatOrchestrator(
    scriptedProvider([
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage}],
      [{type: 'text', text: 'done'}, STOP_DONE],
    ]),
    promptBuilder,
    registryReturning({result: 'r'}),
    {hooks}
  );

  await orchestrator.processMessage(createSession('ask'));

  expect(seen).toEqual(usage);
});

it('returns a schema rejection to the provider as a tool_result so a corrected retry completes the turn', async () => {
  const requests: SendMessageParams[] = [];
  // The orchestrator reuses and mutates one message array across rounds, so round 2's view is captured here.
  let secondRoundMessages: Message[] = [];
  const provider: AIProvider = {
    async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
      requests.push(params);
      if (requests.length === 1) {
        yield {type: 'tool_use', toolCall: {id: 'call-1', name: 'get_weather', input: {}}};
        yield STOP_FOR_TOOL;
        return;
      }
      if (requests.length === 2) {
        secondRoundMessages = [...params.messages];
        yield {type: 'tool_use', toolCall: {id: 'call-2', name: 'get_weather', input: {location: 'Oslo'}}};
        yield STOP_FOR_TOOL;
        return;
      }
      yield {type: 'text', text: 'sunny in Oslo'};
      yield STOP_DONE;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const registry = new ToolRegistry();
  const executorInputs: Array<Record<string, unknown>> = [];
  registry.register(
    {
      name: 'get_weather',
      description: 'gets weather for a location',
      inputSchema: {type: 'object', required: ['location'], properties: {location: {type: 'string'}}},
    },
    async input => {
      executorInputs.push(input);
      return `sunny in ${String(input.location)}`;
    }
  );

