  it('compiles a static inputSchema once at register and reuses it across execute calls', async () => {
    const inputSchema: Record<string, unknown> = {
      type: 'object',
      required: ['city'],
      properties: {city: {type: 'string'}},
    };
    const registry = new ToolRegistry();
    let executions = 0;
    registry.register(
      {
        name: 'pinned_forecast',
        description: 'its schema object is mutated after registration',
        inputSchema,
      },
      async () => {
        executions += 1;
        return 'sunny';
      }
    );
    // A later mutation of the definition's schema object must not change what governs execute.
    inputSchema.required = [];
    inputSchema.properties = {city: {type: 'number'}};

    const rejections: string[] = [];
    for (let call = 0; call < 10; call += 1) {
      rejections.push((await registry.execute('pinned_forecast', {})).result);
    }
    const valid = await registry.execute('pinned_forecast', {city: 'Oslo'});

    expect({
      executions,
      everyRejectionNamesCity: rejections.every(result => /city/.test(result)),
      validStillRuns: valid.result,
    }).toEqual({executions: 1, everyRejectionNamesCity: true, validStillRuns: 'sunny'});
  });
});

